/**
 * Cursor-managed durable files for hosted agents.
 *
 * Requests use the control-plane proxy and deployment pod credential, which
 * scopes access to the deployment. Authors access these files through
 * `ctx.host.files`; Cursor manages the storage bindings, so do not add their
 * names to `hosting.secretNames`.
 *
 * Writes use conditional etags. A raced write surfaces as
 * {@link FileConflictError}, and the backend reports
 * `host.files.capabilities.conflictDetection`.
 */
import { createHash } from "node:crypto";
import { FileConflictError, } from "../files.js";
import { mapBounded } from "../internal/bounded.js";
import { resolveCursorApiBaseUrl, resolveCursorApiFetch, resolveCursorApiKey, } from "../internal/cursor/cursor-api-transport.js";
import { resolveDeploymentStoreSourceIdSync, resolveFrameworkStoreSourceIdSync, resolveStoreProtocolSync, storeProtocolEnablesFactoryFlush, } from "../internal/cursor/hosted-store-secrets.js";
import { createAgentStorePresignedUrlValidatorForBackend } from "./agent-store-presigned-url.js";
const AGENT_SERVE_FILES_PATH = "/v0/agent-serve-files";
/** Managed endpoint for batched file operations. */
const AGENTSDK_STORE_PATH = "/internal/agentsdk/store";
/**
 * Platform-managed identifier for the author-facing file store. Do not add
 * it to `hosting.secretNames`.
 */
